	@Test
	void testFilterNonActivationOffers() {
		CTOfferResponse ctOfferResponse = JsonService
				.getObjectFromJson(TestUtility.loadJson("/FeeCTOfferResponse.json"), CTOfferResponse.class);
		ottCTOffersProcessor.filterNonActivationFeeOffers(ctOfferResponse);
		assertNotNull(ctOfferResponse);
		assertEquals(6, ctOfferResponse.getOffers().size());
	}

	@Test
	void testExcludeUverseCustomerContext() {
		CTOfferRequest ctOfferRequest = new CTOfferRequest();
		CTCustomerContext iptv = new CTCustomerContext();
		iptv.setProductFamily("IPTV");
		CTCustomerContext wireless = new CTCustomerContext();
		wireless.setProductFamily("wireless");
		List<CTCustomerContext> customerContext = new ArrayList<>();
		customerContext.add(iptv);
		customerContext.add(wireless);

		ctOfferRequest.setCustomerContext(customerContext);
		List<CTCustomerContext> custContext = ottCTOffersProcessor.excludeUverseCustomerContext(ctOfferRequest);
		assertNotNull(custContext);
	}

	@Test
	void testGetFeeOffers() throws Exception {
		OfferRequestWrapper offerRequestWrapper = new OfferRequestWrapper();
		OfferRequest offerRequest = JsonService.getObjectFromJson(
				"{\"pagination\":{\"page\":1,\"limit\":100},\"offerActionType\":[\"Acquisition\"],\"offerProductFamily\":[\"OTT\"],\"offerProductTypes\":[\"fee\"],\"salesChannel\":[\"partner\"],\"contractIndicator\":[\"contract\"],\"customerEligibility\":{\"zipCode\":[\"32958\"]}}",
				OfferRequest.class);
		offerRequestWrapper.setPartner(true);
		BenefitsCustomerHasReceived benefitsCustomerHasReceived = new BenefitsCustomerHasReceived();
		benefitsCustomerHasReceived.setBenefitCode("DEACT001");
		offerRequest.setBenefitsCustomerHasReceived(Arrays.asList(benefitsCustomerHasReceived));
		offerRequestWrapper.setOfferRequest(offerRequest);
		CTOfferRequest ctOfferRequest = new CTOfferRequest();
		offerRequestWrapper.setCtOfferRequest(ctOfferRequest);
		CTOfferResponse ctOfferResponse = new CTOfferResponse();
		List<CTOffer> responseList = new ArrayList<>();
		CTOffer ctOffer = new CTOffer();
		OfferAttributes attributes = new OfferAttributes();
		attributes.setOfferProductSubtype(Constants.BASE);
		ctOffer.setAttributes(attributes);
		responseList.add(ctOffer);
		ctOfferResponse.setOffers(responseList);
		offerRequestWrapper.setOfferRequest(offerRequest);

		doReturn(ctOfferResponse).when(cpopClient).getOffers(Mockito.any());
		CTOfferResponse offersResponse = ottCTOffersProcessor.getFeeOffers(offerRequestWrapper);
		assertNotNull(offersResponse);
	}

