    /**
     * SVOD Only Upsell - SLS
     * @throws Exception
     */
    @Test
    void testActiveSubscriptionTypeEligibility() throws Exception {
        java.lang.reflect.Method method = OttCTOffersProcessor.class.getDeclaredMethod(
                "isActiveSubscriptionTypeEligible", CTOffer.class, String.class);
        method.setAccessible(true);

        CTOffer matchingOffer = new CTOffer();
        OfferAttributes matchingAttributes = new OfferAttributes();
        matchingAttributes.setActiveSubscriptionType(Arrays.asList(Constants.GENRE, Constants.ROAD_RUNNER));
        matchingOffer.setAttributes(matchingAttributes);

        CTOffer nonMatchingOffer = new CTOffer();
        OfferAttributes nonMatchingAttributes = new OfferAttributes();
        nonMatchingAttributes.setActiveSubscriptionType(Arrays.asList(Constants.FRONTPORCH_STRING));
        nonMatchingOffer.setAttributes(nonMatchingAttributes);

        CTOffer unrestrictedOffer = new CTOffer();
        unrestrictedOffer.setAttributes(new OfferAttributes());

        assertTrue((Boolean) method.invoke(ottCTOffersProcessor, matchingOffer, Constants.ROAD_RUNNER));
        assertFalse((Boolean) method.invoke(ottCTOffersProcessor, nonMatchingOffer, Constants.ROAD_RUNNER));
        assertTrue((Boolean) method.invoke(ottCTOffersProcessor, unrestrictedOffer, Constants.ROAD_RUNNER));
    }

