    // ===== Tests for reconnectCustomer & filterReconnectOffer =====

    @Test
    @DisplayName("filterReconnectOffer - removes reconnect-only offers when not reconnect flow")
    void testFilterReconnectOffer_removesReconnectOffers() {
        // offer with customerType=reconnect should be filtered out
        CTOffer reconnectOffer = new CTOffer();
        OfferAttributes reconnectAttrs = new OfferAttributes();
        reconnectAttrs.setCustomerTypes(Arrays.asList(Constants.RECONNECT));
        reconnectAttrs.setBillingCode("RECON_CODE");
        reconnectOffer.setAttributes(reconnectAttrs);

        // offer with no customerType should stay
        CTOffer normalOffer = new CTOffer();
        OfferAttributes normalAttrs = new OfferAttributes();
        normalAttrs.setCustomerTypes(null);
        normalAttrs.setBillingCode("NORMAL_CODE");
        normalOffer.setAttributes(normalAttrs);

        when(offersUtils.isCustomerTypeReconnect(reconnectOffer)).thenReturn(true);
        when(offersUtils.isCustomerTypeReconnect(normalOffer)).thenReturn(false);

        List<CTOffer> result = ottCTOffersProcessor.filterReconnectOffer(Arrays.asList(reconnectOffer, normalOffer));

        assertNotNull(result);
        // normal offer should be in the result, reconnect should not
        assertTrue(result.stream().anyMatch(o -> "NORMAL_CODE".equals(o.getAttributes().getBillingCode())));
        assertFalse(result.stream().anyMatch(o -> "RECON_CODE".equals(o.getAttributes().getBillingCode())));
    }

    @Test
    @DisplayName("filterReconnectOffer - empty list returns empty")
    void testFilterReconnectOffer_emptyList_returnsEmpty() {
        List<CTOffer> result = ottCTOffersProcessor.filterReconnectOffer(new ArrayList<>());
        assertNotNull(result);
        assertTrue(result.isEmpty());
    }

    @Test
    @DisplayName("filterReconnectOffer - non-reconnect offer with null customerTypes is included")
    void testFilterReconnectOffer_nullCustomerTypes_offerIsIncluded() {
        CTOffer offer = new CTOffer();
        OfferAttributes attrs = new OfferAttributes();
        attrs.setCustomerTypes(null);
        attrs.setBillingCode("NORMAL_CODE");
        offer.setAttributes(attrs);

        when(offersUtils.isCustomerTypeReconnect(offer)).thenReturn(false);

        List<CTOffer> result = ottCTOffersProcessor.filterReconnectOffer(Arrays.asList(offer));

        assertNotNull(result);
        assertFalse(result.isEmpty());
        assertEquals("NORMAL_CODE", result.get(0).getAttributes().getBillingCode());
    }

